SELECT *,
(SELECT COUNT(*) FROM wizardn.tAthMenu C WHERE C.RoleUid = tAthMenu.RoleUid AND C.ParentMenuCode = tAthMenu.MenuCode) AS ChildCount
FROM wizardn.tAthMenu


        AND ParentMenuCode = #{pParentMenuCode}
        AND MenuLevel = 0

    AND RoleUid = #{pRoleUid}
    AND State = #{pState}

ORDER BY MenuSeq, MenuCode

SELECT IFNULL(MAX(MenuCode),'')
FROM wizardn.tAthMenu

    AND RoleUid = #{roleUid}

        AND ParentMenuCode = #{parentMenuCode}
        AND MenuLevel = 0

