) VALUES (
    #{menuCode}, #{roleUid}, #{menuName}, #{menuUri}, #{parentMenuCode}, #{menuLevel},
    #{menuSeq}, #{state}, #{remark}, NOW(), #{registId}, #{registName}
)

mapper.update:
UPDATE wizardn.tAthMenu SET
    MenuName = #{menuName}, MenuUri = #{menuUri}, MenuSeq = #{menuSeq},
    State = #{state}, Remark = #{remark},
    ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE RoleUid = #{roleUid}
AND MenuCode = #{menuCode}

